
pdfjsLib.GlobalWorkerOptions.workerSrc =
  "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";

const { PDFDocument, StandardFonts, rgb } = PDFLib;
const DEFAULT_PDF_BASE64 = "";

// =========================================================
// RED HAT DISPLAY — tipografía de la constancia
// =========================================================
const RED_HAT_DISPLAY_CSS =
  "https://fonts.googleapis.com/css2?family=Red+Hat+Display:wght@400;800&display=swap";

const FONTKIT_URL =
  "https://unpkg.com/@pdf-lib/fontkit@1.1.1/dist/fontkit.umd.min.js";

let redHatFontBytesPromise = null;
let fontkitPromise = null;


// =========================================================
// CARGAR RED HAT DISPLAY EN LA VISTA PREVIA
// =========================================================
(function loadRedHatDisplayPreviewFont() {
  if (document.querySelector('link[data-red-hat-display="1"]')) return;

  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = RED_HAT_DISPLAY_CSS;
  link.dataset.redHatDisplay = "1";

  link.onload = async () => {
    if (!document.fonts?.load) return;

    try {
      await Promise.all([
        document.fonts.load('400 16px "Red Hat Display"'),
        document.fonts.load('800 16px "Red Hat Display"')
      ]);

      if (pdfMeta) updatePreviewText();
    } catch {}
  };

  document.head.appendChild(link);
})();


// =========================================================
// ESCAPAR HTML
// =========================================================
function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}


// =========================================================
// EVENTO EN NEGRITAS
// =========================================================
function buildBodyRuns(template, data) {
  const source = String(template ?? "");
  const regex = /\{\{(\w+)\}\}/g;

  const runs = [];

  let lastIndex = 0;
  let match;

  while ((match = regex.exec(source))) {

    if (match.index > lastIndex) {
      runs.push({
        text: source.slice(lastIndex, match.index),
        bold: false
      });
    }

    const key = match[1];

    const value = String(data[key] ?? "");

    if (value) {
      runs.push({
        text: value,
        bold: key === "evento"
      });
    }

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < source.length) {
    runs.push({
      text: source.slice(lastIndex),
      bold: false
    });
  }

  return runs;
}


// =========================================================
// PÁRRAFO PARA LA VISTA PREVIA
// =========================================================
function fillTemplateHtml(template, data) {
  return buildBodyRuns(template, data)
    .map(run => {

      const value =
        escapeHtml(run.text).replace(/\n/g, "<br>");

      return run.bold
        ? `<strong style="font-weight:800">${value}</strong>`
        : value;

    })
    .join("");
}


// =========================================================
// FONTKIT
// =========================================================
async function ensureFontkit() {

  if (globalThis.fontkit) {
    return globalThis.fontkit;
  }

  if (fontkitPromise) {
    return fontkitPromise;
  }

  fontkitPromise = new Promise((resolve, reject) => {

    const existing =
      document.querySelector('script[data-pdf-fontkit="1"]');

    if (existing) {

      existing.addEventListener(
        "load",
        () => resolve(globalThis.fontkit),
        { once: true }
      );

      existing.addEventListener(
        "error",
        () => reject(new Error("No se pudo cargar fontkit.")),
        { once: true }
      );

      return;
    }

    const script =
      document.createElement("script");

    script.src = FONTKIT_URL;
    script.async = true;
    script.dataset.pdfFontkit = "1";

    script.onload = () => {

      if (globalThis.fontkit) {
        resolve(globalThis.fontkit);
      } else {
        reject(
          new Error(
            "fontkit se cargó, pero no quedó disponible."
          )
        );
      }

    };

    script.onerror =
      () => reject(
        new Error("No se pudo cargar fontkit.")
      );

    document.head.appendChild(script);

  });

  return fontkitPromise;
}


// =========================================================
// OBTENER URL DE RED HAT DISPLAY
// =========================================================
function extractGoogleFontUrl(css, weight) {

  const blocks =
    [...String(css).matchAll(/@font-face\s*\{([\s\S]*?)\}/g)]
      .map(m => m[1])
      .filter(block =>
        new RegExp(
          `font-weight\\s*:\\s*${weight}\\s*;`
        ).test(block)
      );

  if (!blocks.length) {
    throw new Error(
      `No se encontró Red Hat Display ${weight}.`
    );
  }

  const block =
    blocks[blocks.length - 1];

  const match =
    block.match(/src\s*:\s*url\(([^)]+)\)/);

  if (!match) {
    throw new Error(
      `No se encontró el archivo de Red Hat Display ${weight}.`
    );
  }

  return match[1]
    .replace(/["']/g, "")
    .trim();
}


// =========================================================
// DESCARGAR RED HAT DISPLAY
// =========================================================
async function getRedHatFontBytes() {

  if (redHatFontBytesPromise) {
    return redHatFontBytesPromise;
  }

  redHatFontBytesPromise =
    (async () => {

      const cssResponse =
        await fetch(RED_HAT_DISPLAY_CSS);

      if (!cssResponse.ok) {
        throw new Error(
          "No se pudo cargar Red Hat Display."
        );
      }

      const css =
        await cssResponse.text();

      const regularUrl =
        extractGoogleFontUrl(css, 400);

      const boldUrl =
        extractGoogleFontUrl(css, 800);

      const [
        regularResponse,
        boldResponse
      ] = await Promise.all([
        fetch(regularUrl),
        fetch(boldUrl)
      ]);

      if (
        !regularResponse.ok ||
        !boldResponse.ok
      ) {
        throw new Error(
          "No se pudieron descargar los archivos de Red Hat Display."
        );
      }

      const [
        regular,
        bold
      ] = await Promise.all([
        regularResponse.arrayBuffer(),
        boldResponse.arrayBuffer()
      ]);

      return {
        regular,
        bold
      };

    })();

  return redHatFontBytesPromise;
}


// =========================================================
// INSERTAR FUENTE EN PDF
// =========================================================
async function embedCertificateFonts(doc) {

  try {

    const fk =
      await ensureFontkit();

    const bytes =
      await getRedHatFontBytes();

    doc.registerFontkit(fk);

    const regular =
      await doc.embedFont(
        bytes.regular,
        { subset: true }
      );

    const bold =
      await doc.embedFont(
        bytes.bold,
        { subset: true }
      );

    return {
      regular,
      bold
    };

  } catch (error) {

    console.warn(
      "No se pudo cargar Red Hat Display; usando Helvetica como respaldo.",
      error
    );

    return {
      regular:
        await doc.embedFont(
          StandardFonts.Helvetica
        ),

      bold:
        await doc.embedFont(
          StandardFonts.HelveticaBold
        )
    };

  }
}


