// =========================================================
// IMPORTAR EXCEL
// =========================================================
$("excelInput")
  .addEventListener(
    "change",
    async e => {

      const file =
        e.target.files[0];

      if (!file) {
        return;
      }

      const buffer =
        await file.arrayBuffer();

      const wb =
        XLSX.read(
          buffer,
          {
            type:
              "array",
            cellDates:
              true
          }
        );

      const ws =
        wb.Sheets[
          wb.SheetNames[0]
        ];

      const grid =
        XLSX.utils
          .sheet_to_json(
            ws,
            {
              header:
                1,
              defval:
                "",
              raw:
                false
            }
          );

      if (
        !grid.length
      ) {

        toast(
          "El archivo está vacío"
        );

        return;
      }

      const expectedNames =
        new Set([
          "nombre",
          "name",
          "alumno",
          "alumna",
          "participante",
          "nombre_completo",
          "nombre_del_alumno"
        ]);

      const header =
        grid[0]
          .map(
            normalizeKey
          );

      let nameCol =
        header.findIndex(
          h =>
            expectedNames.has(
              h
            )
        );

      let parsed =
        [];

      if (
        nameCol >= 0
      ) {

        const cols =
          {};

        header.forEach(
          (h, i) =>
            cols[h] =
              i
        );

        for (
          let r = 1;
          r < grid.length;
          r++
        ) {

          const row =
            grid[r];

          const nombre =
            cleanName(
              row[nameCol]
            );

          if (!nombre) {
            continue;
          }

          parsed.push({

            nombre,

            talleres:
              row[
                cols.talleres
              ] ??
              row[
                cols.taller
              ] ??
              "",

            evento:
              row[
                cols.evento
              ] ??
              "",

            fecha:
              row[
                cols.fecha
              ] ??
              "",

            ciudad:
              row[
                cols.ciudad
              ] ??
              ""

          });

        }

      } else {

        for (
          const row
          of grid
        ) {

          const firstNonEmpty =
            row.find(
              v =>
                String(v)
                  .trim() !==
                ""
            );

          const nombre =
            cleanName(
              firstNonEmpty
            );

          if (nombre) {

            parsed.push({
              nombre
            });

          }

        }

      }

      setParticipants(
        parsed,
        "excel"
      );

      $("excelLoaded")
        .textContent =
          `✓ ${file.name} · ${participants.length.toLocaleString("es-MX")} nombres`;

      toast(
        `${participants.length.toLocaleString("es-MX")} participantes importados`
      );

    }
  );


