// =========================================================
// HEX A RGB
// =========================================================
function hexToRgb01(hex) {

  const n =
    parseInt(
      String(hex)
        .replace(
          "#",
          ""
        ),
      16
    );

  return {

    r:
      (
        (n >> 16) &
        255
      ) /
      255,

    g:
      (
        (n >> 8) &
        255
      ) /
      255,

    b:
      (
        n &
        255
      ) /
      255

  };

}


// =========================================================
// POSICIÓN PDF
// =========================================================
function getOverlayPdfBox(el) {

  const c =
    canvas.getBoundingClientRect();

  const r =
    el.getBoundingClientRect();

  const sx =
    pdfMeta.pdfWidth /
    c.width;

  const sy =
    pdfMeta.pdfHeight /
    c.height;

  return {

    x:
      (
        r.left -
        c.left
      ) *
      sx,

    top:
      (
        r.top -
        c.top
      ) *
      sy,

    width:
      r.width *
      sx

  };

}


// =========================================================
// WRAP SIMPLE
// =========================================================
function wrapText(
  text,
  font,
  size,
  maxWidth
) {

  const result =
    [];

  for (
    const paragraph
    of String(text)
      .split(/\n/)
  ) {

    if (
      !paragraph.trim()
    ) {

      result.push("");
      continue;

    }

    const words =
      paragraph.split(
        /\s+/
      );

    let line =
      "";

    for (
      const word
      of words
    ) {

      const test =
        line
          ? `${line} ${word}`
          : word;

      if (
        font.widthOfTextAtSize(
          test,
          size
        ) <=
        maxWidth
      ) {

        line =
          test;

      } else {

        if (line) {
          result.push(
            line
          );
        }

        line =
          word;

      }

    }

    if (line) {
      result.push(
        line
      );
    }

  }

  return result;

}


// =========================================================
// UNIR SEGMENTOS
// =========================================================
function mergeRichSegment(
  line,
  text,
  bold
) {

  if (!text) {
    return;
  }

  const last =
    line[
      line.length - 1
    ];

  if (
    last &&
    last.bold ===
      bold
  ) {

    last.text +=
      text;

  } else {

    line.push({
      text,
      bold
    });

  }

}


// =========================================================
// WRAP CON EVENTO EN NEGRITA
// =========================================================
function wrapRichText(
  runs,
  regular,
  bold,
  size,
  maxWidth
) {

  const lines =
    [];

  let line =
    [];

  let lineWidth =
    0;

  let pendingSpace =
    false;

  const spaceWidth =
    regular.widthOfTextAtSize(
      " ",
      size
    );

  const flushLine =
    () => {

      lines.push(
        line
      );

      line =
        [];

      lineWidth =
        0;

      pendingSpace =
        false;

    };

  for (
    const run
    of runs
  ) {

    const font =
      run.bold
        ? bold
        : regular;

    const tokens =
      String(
        run.text
      )
        .split(
          /(\n|[ \t]+)/
        )
        .filter(
          Boolean
        );

    for (
      const token
      of tokens
    ) {

      if (
        token ===
        "\n"
      ) {

        flushLine();
        continue;

      }

      if (
        /^[ \t]+$/
          .test(
            token
          )
      ) {

        pendingSpace =
          line.length >
          0;

        continue;

      }

      const wordWidth =
        font
          .widthOfTextAtSize(
            token,
            size
          );

      const beforeWidth =
        pendingSpace &&
        line.length
          ? spaceWidth
          : 0;

      if (
        line.length &&
        lineWidth +
          beforeWidth +
          wordWidth >
          maxWidth
      ) {

        flushLine();

      }

      if (
        pendingSpace &&
        line.length
      ) {

        mergeRichSegment(
          line,
          " ",
          false
        );

        lineWidth +=
          spaceWidth;

      }

      mergeRichSegment(
        line,
        token,
        run.bold
      );

      lineWidth +=
        wordWidth;

      pendingSpace =
        false;

    }

  }

  if (
    line.length ||
    !lines.length
  ) {

    lines.push(
      line
    );

  }

  return lines;

}


// =========================================================
// AJUSTAR TAMAÑO DE FUENTE
// =========================================================
function fitFontSize(
  font,
  text,
  maxWidth,
  preferred,
  min = 15
) {

  let size =
    preferred;

  while (
    size > min &&
    font.widthOfTextAtSize(
      text,
      size
    ) >
      maxWidth
  ) {

    size -=
      .5;

  }

  return size;

}


// =========================================================
// NOMBRE DE ARCHIVO
// =========================================================
function safeFileName(s) {

  return String(
    s ||
    "constancia"
  )
    .normalize("NFD")
    .replace(
      /[\u0300-\u036f]/g,
      ""
    )
    .replace(
      /[\\/:*?"<>|]/g,
      ""
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();

}


// =========================================================
// DIBUJAR TEXTO EN LA CONSTANCIA
// =========================================================
function drawCertificateText(
  page,
  regular,
  bold,
  data
) {

  const nameBox =
    getOverlayPdfBox(
      nameOverlay
    );

  const bodyBox =
    getOverlayPdfBox(
      bodyOverlay
    );

  const nc =
    hexToRgb01(
      $("nameColor").value
    );

  const bc =
    hexToRgb01(
      $("bodyColor").value
    );

  const preferredNameSize =
    Number(
      $("nameSize").value
    );

  const bodySize =
    Number(
      $("bodySize").value
    );


  // =====================================================
  // NOMBRE EN RED HAT DISPLAY BOLD Y MAYÚSCULAS
  // =====================================================

  const nameSize =
    fitFontSize(
      bold,
      data.nombre,
      nameBox.width,
      preferredNameSize,
      13
    );

  const nameWidth =
    bold.widthOfTextAtSize(
      data.nombre,
      nameSize
    );

  page.drawText(
    data.nombre,
    {

      x:
        nameBox.x +
        Math.max(
          0,
          (
            nameBox.width -
            nameWidth
          ) /
          2
        ),

      y:
        pdfMeta.pdfHeight -
        nameBox.top -
        nameSize,

      size:
        nameSize,

      font:
        bold,

      color:
        rgb(
          nc.r,
          nc.g,
          nc.b
        )

    }
  );


  // =====================================================
  // PÁRRAFO
  // SOLO EL EVENTO VA EN NEGRITAS
  // =====================================================

  const runs =
    buildBodyRuns(
      $("bodyTemplate").value,
      data
    );

  const lines =
    wrapRichText(
      runs,
      regular,
      bold,
      bodySize,
      bodyBox.width
    );

  const lineHeight =
    bodySize *
    1.35;

  let y =
    pdfMeta.pdfHeight -
    bodyBox.top -
    bodySize;

  for (
    const line
    of lines
  ) {

    if (
      y < 25
    ) {
      break;
    }

    let x =
      bodyBox.x;

    for (
      const segment
      of line
    ) {

      const font =
        segment.bold
          ? bold
          : regular;

      page.drawText(
        segment.text,
        {

          x,
          y,

          size:
            bodySize,

          font,

          color:
            rgb(
              bc.r,
              bc.g,
              bc.b
            )

        }
      );

      x +=
        font.widthOfTextAtSize(
          segment.text,
          bodySize
        );

    }

    y -=
      lineHeight;

  }

}


// =========================================================
// DESCARGAR ARCHIVO
// =========================================================
function downloadBlob(
  blob,
  filename
) {

  const url =
    URL.createObjectURL(
      blob
    );

  const a =
    document.createElement(
      "a"
    );

  a.href =
    url;

  a.download =
    filename;

  document.body.appendChild(
    a
  );

  a.click();
  a.remove();

  setTimeout(
    () =>
      URL.revokeObjectURL(
        url
      ),
    1500
  );

}


