// =========================================================
// PROGRESO
// =========================================================
function showProgress(
  message,
  percent
) {

  $("progress")
    .classList.add(
      "show"
    );

  $("progressMsg")
    .textContent =
      message;

  $("progressBar")
    .style.width =
      `${Math.max(
        0,
        Math.min(
          100,
          percent
        )
      )}%`;

}


// =========================================================
// OCULTAR PROGRESO
// =========================================================
function hideProgressSoon() {

  setTimeout(
    () =>
      $("progress")
        .classList.remove(
          "show"
        ),
    1800
  );

}


// =========================================================
// GENERAR PDF MASIVO
// =========================================================
async function generateCombined() {

  if (
    !participants.length ||
    !templateBytes
  ) {
    return;
  }

  setBusy(
    true
  );

  try {

    showProgress(
      "Preparando PDF masivo...",
      2
    );

    const source =
      await PDFDocument.load(
        templateBytes.slice()
      );

    const out =
      await PDFDocument.create();

    const {
      regular,
      bold
    } =
      await embedCertificateFonts(
        out
      );

    for (
      let i = 0;
      i <
        participants.length;
      i++
    ) {

      const [page] =
        await out.copyPages(
          source,
          [0]
        );

      out.addPage(
        page
      );

      drawCertificateText(
        page,
        regular,
        bold,
        rowData(
          participants[i]
        )
      );

      if (
        i % 10 === 0 ||
        i ===
          participants.length -
            1
      ) {

        showProgress(
          `Generando ${i + 1} de ${participants.length} páginas...`,
          (
            (
              i + 1
            ) /
            participants.length
          ) *
          92
        );

        await new Promise(
          r =>
            setTimeout(
              r,
              0
            )
        );

      }

    }

    showProgress(
      "Empaquetando PDF...",
      96
    );

    const bytes =
      await out.save();

    downloadBlob(

      new Blob(
        [bytes],
        {
          type:
            "application/pdf"
        }
      ),

      `constancias_${participants.length}_participantes.pdf`

    );

    showProgress(
      "¡PDF listo!",
      100
    );

    toast(
      "PDF masivo generado"
    );

  } catch (err) {

    alert(
      "No se pudo generar el PDF: " +
      err.message
    );

  } finally {

    setBusy(
      false
    );

    hideProgressSoon();

  }

}


// =========================================================
// GENERAR PDF INDIVIDUAL
// =========================================================
async function buildSinglePdf(
  data
) {

  const doc =
    await PDFDocument.load(
      templateBytes.slice()
    );

  const page =
    doc.getPages()[0];

  const {
    regular,
    bold
  } =
    await embedCertificateFonts(
      doc
    );

  drawCertificateText(
    page,
    regular,
    bold,
    data
  );

  return await doc.save();

}


// =========================================================
// GENERAR ZIP
// =========================================================
async function generateZip() {

  if (
    !participants.length ||
    !templateBytes
  ) {
    return;
  }

  setBusy(
    true
  );

  try {

    const zip =
      new JSZip();

    for (
      let i = 0;
      i <
        participants.length;
      i++
    ) {

      const data =
        rowData(
          participants[i]
        );

      const bytes =
        await buildSinglePdf(
          data
        );

      zip.file(

        `${String(
          i + 1
        ).padStart(
          4,
          "0"
        )} - ${safeFileName(
          data.nombre
        )}.pdf`,

        bytes

      );

      showProgress(
        `Creando ${i + 1} de ${participants.length} constancias...`,
        (
          (
            i + 1
          ) /
          participants.length
        ) *
        86
      );

      if (
        i % 5 === 0
      ) {

        await new Promise(
          r =>
            setTimeout(
              r,
              0
            )
        );

      }

    }

    showProgress(
      "Comprimiendo ZIP...",
      92
    );

    const blob =
      await zip
        .generateAsync(

          {
            type:
              "blob",

            compression:
              "DEFLATE",

            compressionOptions:
              {
                level:
                  5
              }
          },

          meta =>
            showProgress(
              "Comprimiendo ZIP...",
              92 +
              meta.percent *
                .08
            )

        );

    downloadBlob(
      blob,
      `constancias_${participants.length}_participantes.zip`
    );

    showProgress(
      "¡ZIP listo!",
      100
    );

    toast(
      "ZIP generado"
    );

  } catch (err) {

    alert(
      "No se pudo generar el ZIP: " +
      err.message
    );

  } finally {

    setBusy(
      false
    );

    hideProgressSoon();

  }

}


